import warnings
from fastapi.responses import ORJSONResponse, UJSONResponse

def test_deprecation():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")

        # Test ORJSONResponse
        try:
            ORJSONResponse({"foo": "bar"})
        except Exception:
            pass

        # Test UJSONResponse
        try:
            UJSONResponse({"foo": "bar"})
        except Exception:
            pass

        # We expect at least two warnings if we implement it in __init__
        # But since they might not be installed, we just check if any warning was issued
        # if we are using the classes.

        # For now, let's just see what happens.
        print(f"Warnings caught: {len(w.warnings)}")
        for warning in w.warnings:
            print(f"Warning: {warning.message}")

if __name__ == "__main__":
    test_deprecation()
